package com.ruoyi.system.service.impl;
import java.util.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.alibaba.fastjson2.JSON; import com.ruoyi.common.core.domain.model.MpLoginUser; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.*; import com.ruoyi.system.mapper.*; import com.ruoyi.system.service.IYcMeetingAnalyticsService;
@Service public class YcMeetingAnalyticsServiceImpl implements IYcMeetingAnalyticsService { @Autowired private YcActivityMapper activityMapper; @Autowired private YcApplyOrderMapper orderMapper; @Autowired private YcCheckinLogMapper checkinMapper; @Autowired private YcHotelOrderMapper hotelMapper; @Autowired private YcMealTicketMapper mealMapper; @Autowired private YcActivityHomeVersionMapper homeMapper; @Autowired private YcMeetingEntryEventMapper eventMapper; @Autowired private YcMeetingFeedbackMapper feedbackMapper;
 @Override public void record(Long activityId,String entryId,String eventType,Map<String,Object> context,MpLoginUser user){if(activityId==null||entryId==null||entryId.length()>100||!("view".equals(eventType)||"click".equals(eventType)||"download".equals(eventType)))throw new ServiceException("invalid event");Map<String,Object> safe=new HashMap<>();if(context!=null){if(context.get("source")!=null)safe.put("source",String.valueOf(context.get("source")).substring(0,Math.min(100,String.valueOf(context.get("source")).length())));if(context.get("targetType")!=null)safe.put("targetType",String.valueOf(context.get("targetType")).substring(0,Math.min(50,String.valueOf(context.get("targetType")).length())));}eventMapper.insert(activityId,entryId,eventType,user==null?null:user.getUserId(),JSON.toJSONString(safe));}
 @Override public Map<String,Object> dashboard(Long activityId){if(activityId==null||activityMapper.selectYcActivityById(activityId)==null)throw new ServiceException("activity not found");Map<String,Object> out=new HashMap<>();out.put("registration",orderMapper.selectOrderStats(activityId));out.put("checkpoints",checkinMapper.selectCheckpointStats(activityId));out.put("hotel",hotelMapper.selectHotelOrderStats(activityId));out.put("meal",mealMapper.selectMealStats(activityId));out.put("feedback",feedbackMapper.selectStats(activityId));out.put("topEntries",eventMapper.topEntries(activityId));YcActivityHomeVersion h=homeMapper.selectLatestPublishedByActivityId(activityId);out.put("publishedHomeVersion",h==null?null:h.getVersionNo());return out;}}
